cd /app && python -c "
import torch
w=torch.load('weights.pt',map_location='cpu',weights_only=True)
print(type(w))
for k,v in w.items():
    print(k, tuple(v.shape), v.dtype)
print('---dataset---')
d=torch.load('dataset.pt',map_location='cpu',weights_only=True)
print(type(d))
if isinstance(d,dict):
    for k,v in d.items(): print(k,type(v), getattr(v,'shape',None), getattr(v,'dtype',None))
elif isinstance(d,(list,tuple)):
    print(len(d)); 
    for x in d: print(type(x),getattr(x,'shape',None))
